SENTINELS = {'data/objects_config.json': '      "slug": "west", "name": "West", "horizons_id": "C/1975 V1-A", "id_type": "smallbody",', 'tools/mirror_objects.py': "                  line. Since slice 2's comets, a comet on an open path's", 'tools/test_mirror_objects.py': "Module updated: October 26, 2026 with Anthropic's Claude Opus 5.5 (L-443,", 'tools/gallery_cache_builder.py': "Module updated: October 26, 2026 with Anthropic's Claude Opus 5.5 (L-443,", 'tools/test_gallery_cache_builder_offline.py': "Module updated: October 26, 2026 with Anthropic's Claude Opus 5.5 (L-443,", 'gallery/assembler/assemble.py': "Module updated: October 26, 2026 with Anthropic's Claude Opus 5.5 (L-443,", 'gallery/assembler/render_spacecraft.py': "render_spacecraft.py - A spacecraft's path, or a comet's on an open path,", 'gallery/assembler/presentation.py': "Module updated: October 26, 2026 with Anthropic's Claude Opus 5.5 (L-443,", 'gallery/solar_system_figures.js': "  // L-479: the orbit's near and far distance. Since L-443 build B part 2", 'documentation/smoke_solar_system_figures.js': '//   6. (L-479) The orbit\'s near and far distance, "Orbit: perihelion q', 'interactive.html': "     Updated: October 26, 2026 with Anthropic's Claude Opus 5.5", 'gallery_maintenance_run.py': "Module updated: October 26, 2026 with Anthropic's Claude Opus 5.5", 'tools/headless/run_room_driver.py': "Updated October 26, 2026 with Anthropic's Claude Opus 5.5 (L-443 build B", 'tools/headless/walk_solar_system_drawer.js': "// Updated October 26, 2026 with Anthropic's Claude Opus 5.5 (L-443 build"}
POST_CALLS = []


def fail(msg):
    print(msg)
    print("NOTHING was written. Undo is not needed.")
    sys.exit(1)


def main():
    same_new = set()
    for rel, content in NEW_FILES:
        full = os.path.join(HERE, *rel.split("/"))
        if os.path.exists(full):
            have = open(full, "rb").read().replace(b"\r\n", b"\n")
            if have == content.encode("utf-8"):
                same_new.add(rel)
                continue
            fail("ERROR: %s already exists and differs from what this patch "
                 "writes. Most likely a copy of the same document saved from "
                 "a download or an attachment: delete it and run this patch "
                 "again." % rel)
    staged = []
    for rel, edits in EDITS:
        path = os.path.join(HERE, *rel.split("/"))
        if not os.path.isfile(path):
            fail("ERROR: not found: %s -- is this file in the right folder?"
                 % path)
        raw = open(path, "rb").read()
        crlf = b"\r\n" in raw
        text = raw.replace(b"\r\n", b"\n").decode("utf-8")
        if SENTINELS.get(rel) and SENTINELS[rel] in text:
            fail("ERROR: %s already carries this patch's change; this "
                 "patch has run." % rel)
        for k, (old, new) in enumerate(edits):
            n = text.count(old)
            if n != 1:
                if new and text.count(new) == 1 and old not in text:
                    fail("ERROR: %s already carries edit %d of %d; this "
                         "patch has run." % (rel, k + 1, len(edits)))
                fail("ANCHOR FAIL in %s, edit %d of %d: expected 1 match, "
                     "found %d" % (rel, k + 1, len(edits), n))
            text = text.replace(old, new)
        staged.append((rel, path, text, crlf, len(edits)))
    for rel, path, text, crlf, n in staged:
        open(path, "wb").write(text.encode("utf-8"))
        print("ok  %s (%d edits)" % (rel, n))
        if crlf:
            print("note: %s was CRLF in the working copy; written LF" % rel)
        bad = sum(1 for c in text if ord(c) > 127)
        if bad:
            print("note: %s holds %d non-ASCII character(s) this patch did "
                  "not add" % (rel, bad))
    for rel, content in NEW_FILES:
        full = os.path.join(HERE, *rel.split("/"))
        if rel in same_new:
            print("ok  %s: already there, identical" % rel)
            continue
        d = os.path.dirname(full)
        if d and not os.path.isdir(d):
            os.makedirs(d)
        open(full, "wb").write(content.encode("utf-8"))
        print("ok  %s: new" % rel)
    for name in POST_CALLS:
        for line in globals()[name](HERE):
            print(line)
    print(DONE % (len(staged), len(NEW_FILES)))


if __name__ == "__main__":
    main()
